(()=>{const question=document.querySelector('#ride-question'),screen=document.querySelector('#race-screen'),curtain=document.querySelector('#ride-curtain'),back=document.querySelector('#race-return'),mute=document.querySelector('#race-mute');let horse,frame,busy=false;const music=new Audio('race/music.m4a');music.loop=true;music.preload='none';const delay=()=>new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?20:600));
 document.querySelectorAll('.placed-horse').forEach(el=>el.onclick=()=>{horse=el;question.showModal()});document.querySelector('#ride-no').onclick=()=>question.close();
 document.querySelector('#ride-yes').onclick=async()=>{if(busy)return;busy=true;music.volume=0;music.currentTime=0;music.play().catch(()=>{mute.textContent='Play music'});question.close();curtain.querySelector('span').textContent='Let’s ride, partner.';curtain.classList.add('cover');await delay();screen.hidden=false;document.querySelector('main.world').inert=true;document.body.style.overflow='hidden';frame=document.createElement('iframe');frame.title='Cahoot horse race';frame.src='race/race.html';frame.onload=async()=>{await delay();curtain.classList.remove('cover');music.volume=.65;frame.focus();busy=false};screen.append(frame)};
 back.onclick=async()=>{if(busy)return;busy=true;curtain.querySelector('span').textContent='Back to the sky.';curtain.classList.add('cover');music.pause();await delay();frame?.remove();screen.hidden=true;document.querySelector('main.world').inert=false;document.body.style.overflow='';window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'',location.pathname);back.classList.remove('finished');await delay();curtain.classList.remove('cover');document.querySelector('.follow-x').focus({preventScroll:true});busy=false};
 mute.onclick=()=>{if(music.paused){music.play().then(()=>{music.muted=false;mute.textContent='Sound on'}).catch(()=>{});return}music.muted=!music.muted;mute.textContent=music.muted?'Sound off':'Sound on'};
 window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===frame?.contentWindow&&e.data?.type==='cahoot-race-finished'){back.classList.add('finished');back.focus()}});
})();
